<?php
require_once __DIR__ . '/../lib/bootstrap.php';
require_role('student');
$sid=(int)current_user()['id']; $eid=get_int('id'); $pdo=db();
$st=$pdo->prepare("SELECT e.*,s.title subject_title,c.title class_title FROM exams e JOIN subjects s ON s.id=e.subject_id JOIN classes c ON c.id=e.class_id JOIN class_students cs ON cs.class_id=e.class_id AND cs.student_id=? WHERE e.id=? AND e.status='published'");
$st->execute([$sid,$eid]); $exam=$st->fetch();
if(!$exam) exit('آزمون پیدا نشد یا برای شما فعال نیست.');
$nowTs=time(); $startTs=!empty($exam['starts_at'])?strtotime($exam['starts_at']):null; $endTs=!empty($exam['ends_at'])?strtotime($exam['ends_at']):null;
$st=$pdo->prepare('SELECT * FROM attempts WHERE exam_id=? AND student_id=? AND revoked_at IS NULL ORDER BY attempt_no DESC,id DESC');$st->execute([$eid,$sid]);$attempts=$st->fetchAll();
$maxAttempts=1;$attemptCount=count($attempts);
$activeAttempt=null;foreach($attempts as $existing){if(($existing['status']??'')==='in_progress'){$activeAttempt=$existing;break;}}
$grantCheck=$pdo->prepare('SELECT id FROM exam_retake_grants WHERE exam_id=? AND student_id=? AND used_at IS NULL ORDER BY id LIMIT 1');$grantCheck->execute([$eid,$sid]);$availableGrant=$grantCheck->fetchColumn();
if(!$activeAttempt&&!$availableGrant){if($startTs&&$nowTs<$startTs)exit('این آزمون هنوز شروع نشده است. زمان شروع: '.e($exam['starts_at']));if($endTs&&$nowTs>$endTs)exit('مهلت شرکت در این آزمون به پایان رسیده است.');}
if($attemptCount>=$maxAttempts&&!$activeAttempt&&!$availableGrant){$chosen=$attempts[0];foreach($attempts as $candidate){if((float)($candidate['score']??0)>(float)($chosen['score']??0))$chosen=$candidate;}redirect('student/result.php?id='.$chosen['id']);}
$attemptNo=$attemptCount+1;
// تلاش فعال حفظ می‌شود؛ تلاش اضافه فقط با مجوز موردی و مصرف یک‌باره ساخته می‌شود.
if($activeAttempt){$aid=(int)$activeAttempt['id'];$attemptNo=(int)$activeAttempt['attempt_no'];}
else{
  // هر تلاش، سؤال‌های خودش را دارد؛ تلاش‌های بعدی از بانک همان درس و پودمان انتخاب می‌شوند.
  $pdo->beginTransaction();
  try{
    $guard=$pdo->prepare('SELECT id,attempt_no FROM attempts WHERE exam_id=? AND student_id=? AND revoked_at IS NULL ORDER BY attempt_no DESC,id DESC FOR UPDATE');$guard->execute([$eid,$sid]);$locked=$guard->fetchAll();
    $attemptNo=count($locked)+1;
    if($attemptNo>$maxAttempts){$grant=$pdo->prepare('SELECT id FROM exam_retake_grants WHERE exam_id=? AND student_id=? AND used_at IS NULL ORDER BY id LIMIT 1 FOR UPDATE');$grant->execute([$eid,$sid]);$grantId=(int)$grant->fetchColumn();if(!$grantId){$pdo->rollBack();redirect('student/index.php');}}
    $now=date('Y-m-d H:i:s');
    $ins=$pdo->prepare('INSERT INTO attempts(exam_id,student_id,attempt_no,started_at,status,score,percentage) VALUES(?,?,?,?,"in_progress",0,0)');$ins->execute([$eid,$sid,$attemptNo,$now]);$aid=(int)$pdo->lastInsertId();
    if($attemptNo===1){$source=$pdo->prepare('SELECT id,sort_order FROM questions WHERE exam_id=? ORDER BY sort_order,id');$source->execute([$eid]);$sourceRows=$source->fetchAll();}
    else{
      $needed=(int)$pdo->query('SELECT COUNT(*) FROM questions WHERE exam_id='.(int)$eid)->fetchColumn();
      $used=$pdo->prepare('SELECT DISTINCT q.bank_question_id FROM questions q JOIN attempt_questions aq ON aq.question_id=q.id JOIN attempts a ON a.id=aq.attempt_id WHERE a.exam_id=? AND a.student_id=? AND q.bank_question_id IS NOT NULL');$used->execute([$eid,$sid]);$usedIds=array_map('intval',$used->fetchAll(PDO::FETCH_COLUMN));
      $sql='SELECT qb.id FROM question_bank qb WHERE qb.subject_id=? AND qb.is_active=1';$params=[(int)$exam['subject_id']];
      if(trim((string)($exam['chapter']??''))!==''){$sql.=' AND TRIM(qb.chapter)=TRIM(?)';$params[]=$exam['chapter'];}
      if($usedIds){$sql.=' AND qb.id NOT IN ('.implode(',',array_fill(0,count($usedIds),'?')).')';$params=array_merge($params,$usedIds);}
      $sql.=' ORDER BY RAND() LIMIT '.max(1,$needed);$qbank=$pdo->prepare($sql);$qbank->execute($params);$bankIds=array_map('intval',$qbank->fetchAll(PDO::FETCH_COLUMN));
      if(count($bankIds)<$needed){
        // اگر بانک برای ساخت فرم جدید کافی نیست، آزمون باز هم قابل تکرار باشد و همان سؤال‌های آزمون را استفاده کند.
        $source=$pdo->prepare('SELECT id,sort_order FROM questions WHERE exam_id=? ORDER BY sort_order,id');$source->execute([$eid]);$sourceRows=$source->fetchAll();
        if(count($sourceRows)<$needed){throw new RuntimeException('مجموعه سؤال آزمون برای تلاش مجدد در دسترس نیست.');}
      }else{
        $sourceRows=[];$marks=implode(',',array_fill(0,count($bankIds),'?'));$fetch=$pdo->prepare('SELECT qb.* FROM question_bank qb WHERE qb.id IN ('.$marks.')');$fetch->execute($bankIds);
        $order=0;$insertQ=$pdo->prepare('INSERT INTO questions(exam_id,bank_question_id,question_text,image_path,question_type,score,sort_order,reference_answer,rubric) VALUES(?,?,?,?,?,?,?,?,?)');$insertO=$pdo->prepare('INSERT INTO question_options(question_id,option_text,image_path,option_key,is_correct,sort_order) VALUES(?,?,?,?,?,?)');
        foreach($fetch as $b){$insertQ->execute([$eid,$b['id'],$b['question_text'],$b['image_path']??null,$b['question_type'],$b['score'],$order++,$b['reference_answer'],$b['rubric']]);$nq=(int)$pdo->lastInsertId();$ops=$pdo->prepare('SELECT * FROM question_bank_options WHERE bank_question_id=? ORDER BY sort_order,id');$ops->execute([$b['id']]);foreach($ops as $op)$insertO->execute([$nq,$op['option_text'],$op['image_path']??null,$op['option_key'],$op['is_correct'],$op['sort_order']]);$sourceRows[]=['id'=>$nq,'sort_order'=>$order];}
      }
    }
    $map=$pdo->prepare('INSERT INTO attempt_questions(attempt_id,question_id,sort_order) VALUES(?,?,?)');foreach($sourceRows as $i=>$row)$map->execute([$aid,(int)$row['id'],$i]);if($attemptNo>$maxAttempts){$pdo->prepare('UPDATE exam_retake_grants SET used_at=?,used_attempt_id=? WHERE id=?')->execute([$now,$aid,$grantId]);}$pdo->commit();
  }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error','ساخت مجموعه سؤال آزمون انجام نشد.');redirect('student/index.php');}
}
$randomRank=function($key)use($sid,$eid,$attemptNo){return hash('sha256',$sid.'|'.$eid.'|'.$attemptNo.'|'.$key);};
$st=$pdo->prepare('SELECT q.*,GROUP_CONCAT(CONCAT(o.id,"::",o.option_key,"::",o.option_text,"::",COALESCE(o.image_path,"")) ORDER BY o.sort_order SEPARATOR "||") option_data FROM attempt_questions aq JOIN questions q ON q.id=aq.question_id LEFT JOIN question_options o ON o.question_id=q.id WHERE aq.attempt_id=? GROUP BY q.id,aq.sort_order ORDER BY aq.sort_order');$st->execute([$aid]);$questions=$st->fetchAll();
$randomRank=function($key)use($sid,$eid,$attemptNo){return hash('sha256',$sid.'|'.$eid.'|'.$attemptNo.'|'.$key);};usort($questions,function($a,$b)use($randomRank){return strcmp($randomRank($a['id']),$randomRank($b['id']));});foreach($questions as &$question){$options=array_values(array_filter(explode('||',(string)$question['option_data']),fn($x)=>$x!==''));usort($options,function($a,$b)use($randomRank){return strcmp($randomRank('option-'.(explode('::',$a,2)[0]??'')),$randomRank('option-'.(explode('::',$b,2)[0]??'')));});$question['option_data']=implode('||',$options);}unset($question);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->beginTransaction();try{$score=0;$max=0;foreach($questions as $q){$max+=(float)$q['score'];$answer=post_string('q_'.$q['id']);$correct=null;$awarded=$q['question_type']==='short'?null:0;$selected=null;if(in_array($q['question_type'],['mcq','true_false'],true)){foreach(explode('||',(string)$q['option_data']) as $raw){[$oid,$ok,$ot,$oi]=array_pad(explode('::',$raw,4),4,'');if($ok===$answer){$selected=(int)$oid;$correct=(int)$pdo->query('SELECT is_correct FROM question_options WHERE id='.(int)$oid)->fetchColumn();$awarded=$correct?(float)$q['score']:0;break;}}}$score+=$awarded;$z=$pdo->prepare('INSERT INTO answers(attempt_id,question_id,answer_text,selected_option_id,is_correct,awarded_score) VALUES(?,?,?,?,?,?)');$z->execute([$aid,$q['id'],$q['question_type']==='short'?$answer:null,$selected,$correct,$awarded]);}$pct=$max>0?($score/$max*100):0;$z=$pdo->prepare('UPDATE attempts SET submitted_at=?,status="submitted",score=?,percentage=? WHERE id=?');$z->execute([date('Y-m-d H:i:s'),$score,$pct,$aid]);$pdo->commit();audit('submit','attempt',$aid);flash('success','آزمون شما ثبت شد.');redirect('student/result.php?id='.$aid);}catch(Throwable $e){error_log('[exam_submission] attempt='.(int)$aid.' error='.$e->getMessage());if($pdo->inTransaction())$pdo->rollBack();flash('error','ثبت پاسخ‌ها انجام نشد. لطفاً دوباره تلاش کنید.');}}
$title='پاسخ‌گویی آزمون';require __DIR__.'/../partials/header.php';?><h1><?=e($exam['title'])?></h1><div class="card"><div id="examTimer" class="alert info" data-duration="<?=e((string)((int)$exam['duration_minutes']*60))?>" data-exam="<?=e((string)$eid)?>">زمان باقی‌مانده: در حال محاسبه...</div><p><?=e($exam['instructions'])?></p><div class="exam-toc-header"><strong>وضعیت پاسخ‌ها</strong><span><b class="exam-toc-legend unanswered"></b> بی‌پاسخ <b class="exam-toc-legend answered"></b> پاسخ‌داده‌شده</span></div><nav class="exam-toc" aria-label="پیمایش سؤال‌ها"><?php foreach($questions as $i=>$tocQuestion): ?><a class="unanswered" data-question-id="<?=$tocQuestion['id']?>" href="#question-<?=$tocQuestion['id']?>" title="سؤال <?=($i+1)?>: بی‌پاسخ"><?=($i+1)?></a><?php endforeach; ?></nav><p class="muted">درس: <?=e($exam['subject_title'])?> | مدت: <?=$exam['duration_minutes']?> دقیقه | نمره کل: <?=e($exam['total_score'])?> | تلاش <?=e((string)$attemptNo)?> از <?=e((string)$maxAttempts)?></p><form id="examForm" method="post" onsubmit="if(!confirm('هشدار: پس از ثبت نهایی، پاسخ‌ها قابل تغییر نیستند و برای این آزمون تلاش مجدد خودکار وجود ندارد. مطمئن هستید؟'))return false;if(!confirm('این ارسال نهایی و برگشت‌ناپذیر است. برای ثبت قطعی آزمون تأیید می‌کنید؟'))return false;localStorage.removeItem('exam_deadline_<?=$eid?>');localStorage.removeItem('exam_answers_<?=$eid?>');window.examSubmitted=true;this.querySelector('button[type=submit]').disabled=true;return true;"><?=csrf_field()?><?php foreach($questions as $i=>$q):?><div class="question" id="question-<?=$q['id']?>"><div class="question-prompt"><span class="question-number"><?=($i+1)?>.</span><?=question_prompt_html($q['question_text'])?></div><?php if(!empty($q['image_path'])):?><img class="question-image" src="<?=e(url($q['image_path']))?>" alt="تصویر سؤال"><?php endif;?><div class="muted">نمره: <?=e($q['score'])?></div><?php if(in_array($q['question_type'],['mcq','true_false'],true)):foreach(explode('||',(string)$q['option_data']) as $raw):[$oid,$ok,$ot,$oi]=array_pad(explode('::',$raw,4),4,'');if($ot==='')continue;?><label class="option"><input type="radio" name="q_<?=$q['id']?>" value="<?=e($ok)?>"> <?=e($ok)?>) <?=e($ot)?><?php if($oi!==''):?><img class="option-image" src="<?=e(url($oi))?>" alt="تصویر گزینه"><?php endif;?></label><?php endforeach;else:?><textarea name="q_<?=$q['id']?>" placeholder="پاسخ خود را بنویسید..."></textarea><?php endif;?></div><?php endforeach;?><button class="btn btn-success" type="submit">ثبت نهایی آزمون</button></form></div><script>(function(){var box=document.getElementById('examTimer'),form=document.getElementById('examForm');if(!box||!form)return;var key='exam_deadline_'+box.dataset.exam,deadline=Number(localStorage.getItem(key)||0),duration=Number(box.dataset.duration||0);if(!deadline||deadline<Date.now()){deadline=Date.now()+duration*1000;localStorage.setItem(key,String(deadline));}function tick(){var left=Math.max(0,Math.ceil((deadline-Date.now())/1000)),m=Math.floor(left/60),s=left%60;box.textContent='زمان باقی‌مانده: '+m+' دقیقه و '+String(s).padStart(2,'0')+' ثانیه';if(left<=60)box.className='alert warning';if(left<=0){box.textContent='زمان آزمون به پایان رسید؛ پاسخ‌ها در حال ثبت هستند.';localStorage.removeItem(key);var submitButton=form.querySelector('button[type=submit]');if(submitButton)submitButton.disabled=true;form.onsubmit=null;window.examSubmitted=true;form.submit();return;}setTimeout(tick,1000);}tick();})();</script><script>(function(){var form=document.getElementById('examForm'),key='exam_answers_<?=$eid?>';if(!form)return;var saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')||{};}catch(e){}function hasAnswer(questionId){var fields=form.querySelectorAll('[name="q_'+questionId+'"]'),answered=false;Array.prototype.forEach.call(fields,function(el){if((el.type==='radio'&&el.checked)||(el.type!=='radio'&&el.value.trim()!==''))answered=true;});return answered;}function updateStatus(questionId){var link=document.querySelector('.exam-toc a[data-question-id="'+questionId+'"]');if(!link)return;var answered=hasAnswer(questionId);link.classList.toggle('answered',answered);link.classList.toggle('unanswered',!answered);link.title='سؤال '+link.textContent+': '+(answered?'پاسخ‌داده‌شده':'بی‌پاسخ');}Array.prototype.forEach.call(form.querySelectorAll('input[name^="q_"],textarea[name^="q_"]'),function(el){if(el.type==='radio'){if(saved[el.name]===el.value)el.checked=true;}else if(Object.prototype.hasOwnProperty.call(saved,el.name)){el.value=saved[el.name];}var questionId=el.name.substring(2);el.addEventListener('input',function(){save();updateStatus(questionId);});el.addEventListener('change',function(){save();updateStatus(questionId);});});Array.prototype.forEach.call(form.querySelectorAll('.question[id^="question-"]'),function(question){updateStatus(question.id.substring(9));});function save(){var data={};Array.prototype.forEach.call(form.querySelectorAll('input[name^="q_"],textarea[name^="q_"]'),function(el){if(el.type==='radio'){if(el.checked)data[el.name]=el.value;}else if(el.value.trim()!=='')data[el.name]=el.value;});try{localStorage.setItem(key,JSON.stringify(data));}catch(e){}}window.addEventListener('beforeunload',function(event){if(window.examSubmitted)return;event.preventDefault();event.returnValue='پاسخ‌های شما هنوز ثبت نهایی نشده است.';});})();</script><?php require __DIR__.'/../partials/footer.php'; ?>
